    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "च्चेतस्तानपहाय याहि भवनं देवस्य विश्वेशितु-",
          "end": "line"
        },
        {
          "n": 2,
          "text": "निर्दौवारिकनिर्दयोक्त्यपरुषं निःसीमशर्मप्रदम् ॥ ९७ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "प्रियसखि विपद्दण्डव्रातप्रतापपरम्परा",
          "end": "line"
        },
        {
          "n": 2,
          "text": "परिचयचले चिन्ताचक्रे निधाय विधिः खलः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मृदमिव बलात्पिण्डीकृत्य प्रगल्भकुलालव-",
          "end": "line"
        },
        {
          "n": 4,
          "text": "",
          "end": "join"
        },
        {
          "n": 5,
          "text": "द्भ्रमयति मनो नो जानीमः किमत्र विधास्यति ॥ ९८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "महेश्वरे वा जगतामधीश्वरे",
          "end": "line"
        },
        {
          "n": 2,
          "text": "जनार्दने वा जगदन्तरात्मनि ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "तयोर्न भेदप्रतिपत्तिरस्ति मे",
          "end": "line"
        },
        {
          "n": 4,
          "text": "तथापि भक्तिस्तरुणेन्दुशेखरे ॥ ९९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "रे कन्दर्प करं कदर्थयसि किं कोदण्डटङ्कारवै",
          "end": "line"
        },
        {
          "n": 2,
          "text": "रे रे कोकिल कोमलैः कलरवैः किं त्वं वृथा जल्पसि ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मुग्धे स्निग्धविदग्धमुग्धमधुरैर्लोलैः कटाक्षैरलं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "चेतश्चुम्बितचन्द्रचूडचरणध्यानामृतं वर्तते ॥ १०० ॥",
          "end": "space"
        },
        {
          "n": 5,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "apparatus_entry",
